import { atom, read, update } from 'claude-code';
import type { EngineInterface, On, ToolCallResult } from 'claude-code';

import { MANUALS_FEATURE } from '../shared/catalog';
import { cliArgv } from '../shared/cli';
import { TURN_REASONS } from '../shared/turns';
import {
  CLAUDE_FILES,
  HOME_MARKERS,
  MAX_IMPORT_HOPS,
  dataDirNameIn,
  expandHome,
  foldersUpTo,
  grantFor,
  hasOwnContent,
  importsIn,
  isUnder,
  manualContext,
  normalize,
  parentOf,
  pathsInCommand,
  resolveImport,
  shortName
} from './repo';

// `${loop}:${path}` for each file attached and `${loop}:${folder}/` for each folder already read.
const delivered = atom({ plugin: 'agent-kevin', key: 'delivered' } as const, []);
// Files the current turn attached, shown in the band until the turn ends.
const thisTurn = atom({ plugin: 'agent-kevin', key: 'manualsThisTurn' } as const, []);

const MAIN = 'main';

// Read once per module load; a reload picks up changed grants.
let grantsCache: string[] | undefined;
let dataDirCache: string | undefined;

interface Manual {
  path: string;
  text: string;
}

const loopOf = (agentId: string | undefined): string => agentId ?? MAIN;

const asPaths = (field: unknown): string[] => (typeof field === 'string' ? [field] : []);

async function exists($: EngineInterface, path: string): Promise<boolean> {
  return $.fs.stat(path).then(
    () => true,
    () => false
  );
}

async function grants($: EngineInterface): Promise<string[]> {
  if (grantsCache) {
    return grantsCache;
  }
  const permissions = (await $.settings.read()).permissions;
  const listed =
    typeof permissions === 'object' && permissions !== null && 'additionalDirectories' in permissions
      ? permissions.additionalDirectories
      : [];
  const home = await $.env.get('HOME');
  grantsCache = (Array.isArray(listed) ? listed : [])
    .filter((entry): entry is string => typeof entry === 'string')
    .map((entry) => expandHome(entry, home));
  return grantsCache;
}

/**
 * The plugin's data dir name (`.state`), from the CLI that owns it; '' when it can't be read.
 */
async function dataDirName($: EngineInterface): Promise<string> {
  if (dataDirCache === undefined) {
    const { exitCode, stdout } = await $.process.run(cliArgv($.plugin.root, $.plugin.name, ['ping']), {
      cwd: await $.session.root()
    });
    dataDirCache = exitCode === 0 ? dataDirNameIn(stdout) : '';
  }
  return dataDirCache;
}

/**
 * An agent home loads its own instructions through its bridge; it is marked, as the runtime marks
 * one, by a data dir holding a marker file.
 */
async function isAgentHome($: EngineInterface, folder: string): Promise<boolean> {
  const name = await dataDirName($);
  if (!name) {
    return false;
  }
  const marked = await Promise.all(HOME_MARKERS.map((marker) => exists($, `${folder}/${name}/${marker}`)));
  return marked.includes(true);
}

async function findRepoRoot($: EngineInterface, folders: readonly string[]): Promise<string | undefined> {
  const [first, ...rest] = folders;
  if (first === undefined) {
    return undefined;
  }
  return (await exists($, `${first}/.git`)) ? first : findRepoRoot($, rest);
}

/**
 * The repo folders from the root down to `path`'s folder that this loop hasn't read yet, or none
 * outside a granted repo and inside an agent home.
 */
async function foldersFor(
  $: EngineInterface,
  path: string,
  mayBeFolder: boolean,
  done: ReadonlySet<string>
): Promise<string[]> {
  const grant = grantFor(path, await grants($), await $.session.root());
  if (grant === undefined) {
    return [];
  }
  const isFolder =
    mayBeFolder &&
    (await $.fs.stat(path).then(
      (stat) => stat.kind === 'dir',
      () => false
    ));
  const folder = isFolder ? path : parentOf(path);
  // Handling a folder marks every folder from its repo root down, so a repeat touch stops here.
  if (done.has(`${folder}/`)) {
    return [];
  }
  const upward = foldersUpTo(folder, grant);
  const repoRoot = await findRepoRoot($, upward);
  if (repoRoot === undefined || (await isAgentHome($, repoRoot))) {
    return [];
  }
  return upward.slice(0, upward.indexOf(repoRoot) + 1).reverse();
}

/**
 * A folder's Claude files, or its AGENTS.md when it has none: Claude Code's default rule.
 */
async function instructionFiles($: EngineInterface, folder: string): Promise<string[]> {
  const present = async (paths: readonly string[]) =>
    (await Promise.all(paths.map(async (path) => ((await exists($, path)) ? [path] : [])))).flat();
  const claude = await present(CLAUDE_FILES.map((name) => `${folder}/${name}`));
  return claude.length ? claude : present([`${folder}/AGENTS.md`]);
}

/**
 * Each file then its imports, depth-first, skipping anything already seen and any import
 * outside the grants (the mod reads files the Read tool's sandbox would refuse).
 */
async function expand(
  $: EngineInterface,
  files: readonly string[],
  hops: number,
  walk: { allowed: readonly string[]; home: string | undefined; seen: Set<string> }
): Promise<Manual[]> {
  const [file, ...rest] = files;
  if (file === undefined) {
    return [];
  }
  if (walk.seen.has(file)) {
    return expand($, rest, hops, walk);
  }
  walk.seen.add(file);
  const text = await $.fs.read(file).catch(() => undefined);
  if (typeof text !== 'string') {
    return expand($, rest, hops, walk);
  }
  const imports =
    hops >= MAX_IMPORT_HOPS
      ? []
      : importsIn(text)
          .map((ref) => resolveImport(file, ref, walk.home))
          .filter((path) => walk.allowed.some((grant) => isUnder(path, grant)));
  const nested = await expand($, imports, hops + 1, walk);
  return [{ path: file, text }, ...nested, ...(await expand($, rest, hops, walk))];
}

async function withManuals(
  $: EngineInterface,
  result: ToolCallResult,
  spelled: readonly string[],
  mayBeFolder: boolean,
  agentId: string | undefined
): Promise<ToolCallResult> {
  const touched = spelled.map(normalize);
  if (result.deny !== undefined || touched.length === 0) {
    return result;
  }
  const loop = loopOf(agentId);
  const done = new Set(
    (await read($, delivered)).filter((key) => key.startsWith(`${loop}:`)).map((key) => key.slice(loop.length + 1))
  );
  const folders = [
    ...new Set((await Promise.all(touched.map((path) => foldersFor($, path, mayBeFolder, done)))).flat())
  ].filter((folder) => !done.has(`${folder}/`));
  if (folders.length === 0) {
    return result;
  }
  const files = (await Promise.all(folders.map((folder) => instructionFiles($, folder)))).flat();
  const manuals = await expand($, files, 0, {
    allowed: await grants($),
    home: await $.env.get('HOME'),
    seen: new Set([...done, ...touched])
  });
  const shown = manuals.filter((manual) => hasOwnContent(manual.text));
  await update($, delivered, (list) => [
    ...list,
    ...folders.map((folder) => `${loop}:${folder}/`),
    ...shown.map((manual) => `${loop}:${manual.path}`)
  ]);
  if (loop === MAIN && shown.length) {
    await update($, thisTurn, (list) => [...list, ...shown.map((manual) => manual.path)]);
  }
  return shown.length
    ? {
        ...result,
        context: [...(result.context ?? []), ...shown.map((manual) => manualContext(manual.path, manual.text))]
      }
    : result;
}

export const registerManuals = (on: On): void => {
  // Edit refuses a file the conversation hasn't Read, so the Read already attached its manual.
  on('tool.call', { tool: ['Read', 'Write'] }, async ($, e, next) =>
    withManuals($, await next(e), asPaths(e.file_path), false, e.agentId)
  );

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const result = await next(e);
    return withManuals($, result, pathsInCommand(asPaths(e.command)[0] ?? '', await grants($)), true, e.agentId);
  });

  // A precompute only prepares a summary and a vetoed one changes nothing: the manuals stay in context.
  on('session.compact', { trigger: ['manual', 'auto', 'plugin'] }, async ($, e, next) => {
    const result = await next(e);
    if (result.skip === undefined) {
      const prefix = `${loopOf(e.agentId)}:`;
      await update($, delivered, (list) => list.filter((key) => !key.startsWith(prefix)));
    }
    return result;
  });

  // A /clear or a resume starts another conversation in the same process.
  on('session.end', { reason: ['clear', 'resume'] }, async ($, e, next) => {
    await update($, delivered, () => []);
    return next(e);
  });

  // Sync owns the unmatched turn.complete; every reason is listed so this one sees each turn too.
  on('turn.complete', { reason: TURN_REASONS }, async ($, e, next) => {
    if (e.agentId === undefined) {
      await update($, thisTurn, () => []);
    }
    return next(e);
  });

  on('session.start', { isInteractive: true }, async ($, e, next) => {
    await Promise.all(MANUALS_FEATURE.commands.map((command) => $.command.register(command)));
    return next(e);
  });

  on('command.run', { command: 'manuals' }, async ($) => {
    const allowed = await grants($);
    const files = (await read($, delivered))
      .filter((key) => key.startsWith(`${MAIN}:`) && !key.endsWith('/'))
      .map((key) => shortName(key.slice(MAIN.length + 1), allowed));
    return { text: files.length ? `In context: ${files.join(', ')}` : 'No repo instructions attached yet.' };
  });

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const below = await next(e);
    const attached = await read($, thisTurn);
    if (attached.length === 0 || e.props.hasSurvey) {
      return below;
    }
    const allowed = await grants($);
    const { Box, Text } = $.ui.resolve(e);
    return (
      <Box flexDirection="column">
        <Text dimColor wrap="truncate-end">
          📎 {attached.map((path) => shortName(path, allowed)).join(' · ')} attached
        </Text>
        {below}
      </Box>
    );
  });
};

files.notices/notices.tsx:
import { atom, read, update } from 'claude-code';
import type { EngineInterface, On, Timer } from 'claude-code';

import { cliArgv, cliError } from '../shared/cli';
import { TURN_REASONS } from '../shared/turns';
import { SYNC_HISTORY_KEY, formatDuration, parseHistory, typicalMs } from '../sync/stats';
import type { Notice, NoticeActing } from '../types';

const notices = atom({ plugin: 'agent-kevin', key: 'notices' } as const, []);
// The notice whose command was pressed or started; the row steps aside until that command's turn ends.
const acting = atom({ plugin: 'agent-kevin', key: 'noticeActing' } as const, null);

const REFRESH_MS = 30 * 60_000;
const TOAST_MS = 8000;

const LEVEL_COLORS = { hint: 'cyan', nudge: 'yellow', alert: 'red' } as const;
const TONE_COLORS = { accent: 'cyan', warn: 'yellow' } as const;

// Module state: a reload drops the timer and the next session start makes a new one.
let refresher: Timer | undefined;
// Claimed before the press's first await, so a second press in the same tick finds it.
let isPressing = false;

const actsOn = (notice: Notice, skill: string): boolean =>
  notice.command === skill || notice.command.endsWith(`:${skill}`);

const isString = (data: unknown): data is string => typeof data === 'string';

const isNotice = (data: unknown): data is Notice => {
  if (typeof data !== 'object' || data === null) {
    return false;
  }
  const item = data as Record<string, unknown>;
  return (
    [item.id, item.icon, item.title, item.command, item.actionLabel].every(isString) &&
    ['hint', 'nudge', 'alert'].includes(String(item.level)) &&
    Array.isArray(item.facts) &&
    item.facts.every(
      (fact: unknown) => typeof fact === 'object' && fact !== null && isString((fact as { text?: unknown }).text)
    )
  );
};

// The CLI is this plugin's own, but a list that isn't one keeps the last good list rather than breaking the band.
const parseNotices = (text: string): Notice[] | null => {
  const data: unknown = JSON.parse(text);
  return Array.isArray(data) && data.every(isNotice) ? data : null;
};

// The session root, not its cwd: a shell `cd` in a turn moves the cwd out of the home.
async function runCli($: EngineInterface, args: readonly string[]): Promise<string> {
  const { exitCode, stdout, stderr } = await $.process.run(cliArgv($.plugin.root, $.plugin.name, args), {
    cwd: await $.session.root()
  });
  if (exitCode !== 0) {
    throw cliError(stderr, args, exitCode);
  }
  return stdout;
}

/**
 * Stores the list a `notices` call prints, the sync notice carrying this machine's typical run time.
 */
async function load($: EngineInterface, args: readonly string[]): Promise<Notice[]> {
  const fresh = await runCli($, args)
    .then(parseNotices)
    .catch(() => null);
  if (fresh === null) {
    return read($, notices);
  }
  const typical = typicalMs(parseHistory(await $.store.get(SYNC_HISTORY_KEY)));
  const shown =
    typical === null
      ? fresh
      : fresh.map((notice) =>
          notice.id === 'sync'
            ? { ...notice, facts: [...notice.facts, { text: `~${formatDuration(typical)}` }] }
            : notice
        );
  await update($, notices, () => shown);
  return shown;
}

async function announce($: EngineInterface): Promise<void> {
  const [lead] = await load($, ['notices', '--row']);
  if (lead === undefined) {
    return;
  }
  void $.prompt.suggest({ text: `/${lead.command}` });
  if (lead.level === 'alert') {
    $.ui.toast(`${lead.icon}  ${lead.title}. Tab to ${lead.actionLabel.toLowerCase()}.`, { timeoutMs: TOAST_MS });
  }
}

async function act($: EngineInterface, notice: Notice): Promise<void> {
  if (isPressing) {
    return;
  }
  isPressing = true;
  try {
    if ((await read($, acting)) !== null) {
      return;
    }
    const at = await $.clock.now();
    await update($, acting, () => ({ id: notice.id, isStarted: false, at }));
  } finally {
    isPressing = false;
  }
  // Queued, not awaited: the run outlives the press. Should a host refuse the name, the typed form does the same.
  void $.command
    .run({ command: notice.command })
    .catch(() => $.prompt.submit({ text: `/${notice.command}` }))
    .catch(() => update($, acting, (current) => (current?.isStarted ? current : null)));
}

async function snooze($: EngineInterface, notice: Notice): Promise<void> {
  await load($, ['notices', 'record', notice.id, '--outcome=snoozed']);
}

async function settle($: EngineInterface): Promise<void> {
  await load($, ['notices']);
  await update($, acting, () => null);
}

// A press whose command never started (the queue dropped it) stops hiding the row once it is a refresh old.
async function refresh($: EngineInterface): Promise<void> {
  await load($, ['notices']);
  const now = await $.clock.now();
  await update($, acting, (current: NoticeActing | null) =>
    current && !current.isStarted && now - current.at >= REFRESH_MS ? null : current
  );
}

export const registerNotices = (on: On): void => {
  on('session.start', { isInteractive: true }, async ($, e, next) => {
    const result = await next(e);
    // After the session is up: the CLI call is a process spawn the prompt shouldn't wait on.
    $.clock.after(0, () => void announce($));
    refresher?.cancel();
    refresher = $.clock.every(REFRESH_MS, () => void refresh($));
    return result;
  });

  // Typing the command by hand counts as acting on it, the same as the button.
  on('skill.prompt', { skill: /./ }, async ($, e, next) => {
    const notice = (await read($, notices)).find((item) => actsOn(item, e.skill));
    if (notice) {
      const at = await $.clock.now();
      await update($, acting, () => ({ id: notice.id, isStarted: true, at }));
      void runCli($, ['notices', 'record', notice.id, '--outcome=acted']).catch(() => undefined);
    }
    return next(e);
  });

  // The command's skill started inside the running turn, so the next main turn to end is the command's own, however it ended.
  on('turn.complete', { reason: TURN_REASONS }, async ($, e, next) => {
    const result = await next(e);
    if (e.agentId === undefined && (await read($, acting))?.isStarted) {
      $.clock.after(0, () => void settle($));
    }
    return result;
  });

  // Stacks above whatever renders beneath, so other features' rows share the band.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const below = await next(e);
    if (e.props.hasSurvey || (await read($, acting)) !== null) {
      return below;
    }
    const [top, ...waiting] = await read($, notices);
    if (top === undefined || top.level === 'hint') {
      return below;
    }
    const { Box, Button, Text } = $.ui.resolve(e);
    return (
      <Box flexDirection="column">
        <Box gap={1}>
          {/* The trailing space survives a font that draws the glyph wider than its one cell. */}
          <Text bold color={LEVEL_COLORS[top.level]}>{`${top.icon} `}</Text>
          <Text bold>{top.title}</Text>
          {top.facts.map((fact) => (
            <Box key={fact.text} gap={1}>
              <Text dimColor>·</Text>
              <Text color={fact.tone ? TONE_COLORS[fact.tone] : undefined} dimColor={!fact.tone}>
                {fact.text}
              </Text>
            </Box>
          ))}
          <Box gap={1} marginLeft={2}>
            <Button
              key={`notice:${top.id}:act`}
              variant="primary"
              label={top.actionLabel}
              onPress={() => act($, top)}
            />
            <Button key={`notice:${top.id}:snooze`} dimColor label="Tomorrow" onPress={() => snooze($, top)} />
          </Box>
          {waiting.length ? <Text dimColor>{`+${waiting.length} more`}</Text> : null}
        </Box>
        {below}
      </Box>
    );
  });
};

